def normalize_email(value):
    return value.strip().lower() if value else None
print(normalize_email('  USER@Example.COM '))

source=[{'id':'1','amount':'10'},{'id':'2','amount':'bad'},{'id':'3','amount':'5'}]
valid=[]; rejects=[]
for r in source:
    try: valid.append({'id':int(r['id']),'amount':float(r['amount'])})
    except (ValueError,KeyError): rejects.append(r)
total=sum(r['amount'] for r in valid)
print('loaded:',len(valid),'| rejected:',len(rejects),'| total:',total)

